<script lang="ts">
  let { alerts = [], loading = false, error = '', onRefresh, onDetail, page = 1, pageCount = 1, total = 0, onPageChange, formatDate, duration, confidence, labelClass, statusLabel } = $props<any>();
  function isInterrupted(alert: any) { return String(alert.status ?? '').toLowerCase() === 'interrupted'; }
  function isActive(alert: any) { return String(alert.status ?? '').toLowerCase() === 'active'; }
</script>

<section class="alerts-view surface" aria-labelledby="events-title">
  <header class="events-header">
    <div class="events-heading"><span class="eyebrow">CENTRO DE INCIDENTES</span><h2 id="events-title">Eventos confirmados</h2><p>La clase se consolida al cerrar el evento; el puntaje corresponde a VadCLIP.</p></div>
    <div class="events-actions"><span class="event-count" aria-label={`${total} eventos`}>{total}<small>eventos</small></span><button class="refresh-button" type="button" onclick={onRefresh} disabled={loading} aria-label="Actualizar eventos"><span aria-hidden="true">↻</span>{loading ? 'Actualizando' : 'Actualizar'}</button></div>
  </header>
  {#if error}<div class="banner error" role="alert"><strong>No se pudieron actualizar los eventos</strong><span>{error}</span></div>{/if}
  {#if alerts.length}
    <div class="event-list" aria-live="polite">
      {#each alerts as alert, i (alert.id ?? `${alert.fecha_hora}-${i}`)}
        <article class:interrupted={isInterrupted(alert)} class:active={isActive(alert)} class="event-card">
          <div class="event-rail" aria-hidden="true"><span>!</span></div>
          <div class="event-content">
            <div class="event-topline"><div><p class="camera-label"><span aria-hidden="true">◉</span> {alert.camera ?? 'Cámara no identificada'}</p><h3>{labelClass(alert.clase)}</h3></div><span class:status-active={isActive(alert)} class:status-interrupted={isInterrupted(alert)} class="status-pill"><i></i>{statusLabel(alert.status)}</span></div>
            <div class="event-timeline" aria-label="Tiempos del evento"><div><span>INICIO</span><strong>{formatDate(alert.timestamp_inicio ?? alert.fecha_hora)}</strong></div><div class="timeline-line" aria-hidden="true"><i></i></div><div><span>FIN</span><strong>{formatDate(alert.timestamp_fin ?? alert.fecha_hora_fin)}</strong></div><div class="duration"><span>DURACIÓN</span><strong>{duration(alert.duracion_segundos)}</strong></div></div>
            <div class="event-metrics"><span>Anomalía VadCLIP <strong>{confidence(alert.confianza)}</strong></span><span>Umbral de apertura <strong>{confidence(alert.threshold)}</strong></span>{#if isInterrupted(alert) && alert.interruption_reason}<span class="interruption"><strong>Interrupción:</strong> {alert.interruption_reason}</span>{/if}</div>
          </div>
          <button class="detail-button" type="button" onclick={() => onDetail(alert)}>Ver detalle <span aria-hidden="true">→</span></button>
        </article>
      {/each}
    </div>
    {#if pageCount > 1}
      <nav class="pagination" aria-label="Paginación de eventos">
        <span>Mostrando {alerts.length} de {total} eventos</span>
        <div><button type="button" onclick={() => onPageChange(page - 1)} disabled={page <= 1}>← Anterior</button><strong>Página {page} de {pageCount}</strong><button type="button" onclick={() => onPageChange(page + 1)} disabled={page >= pageCount}>Siguiente →</button></div>
      </nav>
    {/if}
  {:else}
    <div class="empty"><span class="placeholder-icon" aria-hidden="true">◇</span><h3>{loading ? 'Consultando eventos…' : 'No hay eventos confirmados'}</h3><p>{loading ? 'Esperando la respuesta del servidor de inferencia.' : 'Los eventos detectados aparecerán aquí con su evidencia.'}</p></div>
  {/if}
</section>

<style>
  .alerts-view{padding:28px;background:linear-gradient(180deg,#fff 0%,#fbfdff 100%)}.events-header{display:flex;align-items:flex-start;justify-content:space-between;gap:24px;padding-bottom:24px;border-bottom:1px solid #e4ebf3}.eyebrow{display:block;color:#37739f;font-size:10px;font-weight:800;letter-spacing:1.55px;margin-bottom:7px}.events-heading h2{margin:0;color:#0c315f;font-size:22px;letter-spacing:-.35px}.events-heading p{margin:7px 0 0;color:#607991;font-size:13px}.events-actions{display:flex;align-items:center;gap:12px}.event-count{min-width:54px;padding:7px 10px;border:1px solid #dce7f1;border-radius:9px;background:#f5f9fc;color:#0c4b86;text-align:center;font-size:18px;font-weight:800;line-height:1}.event-count small{display:block;margin-top:4px;color:#6b8198;font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.65px}.refresh-button,.detail-button,.pagination button{border:0;font:inherit;font-weight:750;cursor:pointer;transition:.18s ease}.refresh-button{display:inline-flex;align-items:center;gap:7px;padding:11px 14px;border-radius:8px;background:#edf4fb;color:#15538d;font-size:12px}.refresh-button:hover{background:#dfeefa}.refresh-button:disabled,.pagination button:disabled{cursor:not-allowed;opacity:.45}.refresh-button span{font-size:17px;line-height:.6}.event-list{display:grid;gap:12px;margin-top:20px}.event-card{position:relative;display:grid;grid-template-columns:5px minmax(0,1fr) auto;gap:18px;align-items:center;overflow:hidden;border:1px solid #e1eaf2;border-radius:11px;background:#fff;box-shadow:0 2px 7px #173b6210;transition:.18s}.event-card:hover{border-color:#bdd4e8;box-shadow:0 8px 20px #173b6218;transform:translateY(-1px)}.event-rail{height:100%;background:#2079bd;display:grid;place-items:start center;padding-top:20px}.event-rail span{display:grid;place-items:center;width:21px;height:21px;border:2px solid #e9f5ff;border-radius:50%;color:#fff;font-size:13px;font-weight:900}.event-card.interrupted .event-rail{background:#ce7b44}.event-card.active .event-rail{background:#118874}.event-content{min-width:0;padding:17px 0}.event-topline{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.camera-label{margin:0 0 4px;color:#47708e;font-size:11px;font-weight:750}.camera-label span{color:#1594cb}.event-topline h3{margin:0;color:#153c67;font-size:16px;text-transform:capitalize}.status-pill{display:inline-flex;align-items:center;gap:6px;flex:0 0 auto;padding:6px 9px;border-radius:20px;background:#eef3f8;color:#49667f;font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.35px}.status-pill i{width:6px;height:6px;border-radius:50%;background:#7d91a4}.status-pill.status-active{background:#e7f7f2;color:#087461}.status-pill.status-active i{background:#16aa88;box-shadow:0 0 0 3px #16aa8824}.status-pill.status-interrupted{background:#fff2e9;color:#a55a2e}.status-pill.status-interrupted i{background:#da824a}.event-timeline{display:grid;grid-template-columns:minmax(130px,1fr) 42px minmax(130px,1fr) minmax(86px,.65fr);align-items:center;gap:10px;margin-top:16px;padding:11px 13px;border-radius:7px;background:#f5f8fb}.event-timeline span{display:block;margin-bottom:3px;color:#8092a5;font-size:9px;font-weight:800;letter-spacing:.7px}.event-timeline strong{display:block;color:#36536e;font-size:11px;font-weight:700}.timeline-line{display:flex;align-items:center;gap:0}.timeline-line:before,.timeline-line:after{content:"";height:1px;flex:1;background:#b9ccdc}.timeline-line i{width:6px;height:6px;border:2px solid #4d91c3;border-radius:50%;background:#fff}.duration{padding-left:13px;border-left:1px solid #dce5ed}.duration strong{color:#0e5a97}.event-metrics{display:flex;flex-wrap:wrap;gap:10px 18px;margin-top:12px;color:#73889c;font-size:11px}.event-metrics strong{color:#385873}.event-metrics .interruption{flex-basis:100%;color:#a45e32}.detail-button{align-self:center;margin-right:19px;padding:10px 13px;border-radius:7px;background:#075dad;color:#fff;font-size:11px;white-space:nowrap}.detail-button:hover{background:#064e91}.detail-button span{font-size:15px;margin-left:4px}.pagination{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-top:18px;padding:14px 3px 0;color:#657e95;font-size:12px}.pagination>div{display:flex;align-items:center;gap:12px}.pagination button{padding:7px 10px;border:1px solid #d5e1ec;border-radius:6px;background:#fff;color:#215987;font-size:11px}.pagination button:not(:disabled):hover{background:#eff6fc}.pagination strong{color:#385873;font-size:11px}.empty{text-align:center;padding:60px 20px;color:#5d768e}.empty h3{margin:10px 0 7px;color:#244768}.empty p{margin:0;font-size:13px}.placeholder-icon{display:grid;place-items:center;width:50px;height:50px;margin:auto;border-radius:15px;background:#edf5fc;color:#2079bd;font-size:27px}.banner{display:flex;gap:12px;padding:13px 16px;margin-top:18px;border:1px solid #eed9ce;border-radius:7px;background:#fff7f2;color:#8c5038;font-size:12px}@media(max-width:760px){.alerts-view{padding:20px}.events-header{align-items:center}.events-heading p{display:none}.event-card{grid-template-columns:5px minmax(0,1fr)}.event-content{padding:16px 15px 8px 0}.detail-button{grid-column:2;margin:0 15px 16px;justify-self:stretch}.event-timeline{grid-template-columns:1fr 1fr}.timeline-line{display:none}.duration{padding:10px 0 0;border:0;border-top:1px solid #dce5ed}.event-topline{align-items:center}.pagination{align-items:flex-start;flex-direction:column}}@media(max-width:480px){.events-actions{gap:6px}.refresh-button{padding:10px;font-size:0}.refresh-button span{font-size:18px}.event-timeline{gap:8px;padding:10px}.event-topline h3{font-size:14px}.status-pill{font-size:9px}}
</style>
